contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 d, uint256 w) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0);
        require(address(this).balance >= d);
        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint256 balAfterDeposit = address(c).balance;
        bool reverted;
        c.withdraw(w); if (__ESBMC_reverted()) return;
        reverted = false;
        if (w > d) { reverted = true; }
        assert((!reverted && address(c).balance == balAfterDeposit - w) || (reverted && w > d));
    }
    receive() external payable {}
}

